// Sheet columns: Type (youtube | threads), URL. YouTube: /@handle, /c/name, or /channel/UC... URLs.
const rows = $input.all().map(i => i.json);
const channelUrls = rows
  .filter(r => String(r.Type ?? '').trim().toLowerCase() === 'youtube')
  .map(r => String(r.URL ?? '').trim())
  .filter(u => /^https?:\/\/(www\.|m\.)?youtube\.com\//i.test(u));
return [...new Set(channelUrls)].map(channelUrl => ({ json: { channelUrl } }));

const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
return $input.all().filter(item => {
  const dateValue = item.json.publishedAt || item.json.isoDate || item.json.pubDate || item.json.updated || item.json.published;
  const entryDate = dateValue ? new Date(dateValue) : null;
  return entryDate && !Number.isNaN(entryDate.getTime()) && entryDate >= sevenDaysAgo;
});

