const results = [];
for (const item of $input.all()) {
  const pageHtml = String(item.json.pageHtml ?? item.json.data ?? '');
  const channelId = pageHtml.match(/(?:youtube\.com\/channel\/|feeds\/videos\.xml\?channel_id=)(UC[A-Za-z0-9_-]{22})/i)?.[1];
  if (!channelId) throw new Error(`Could not resolve a YouTube channel ID from ${item.json.channelUrl ?? 'the fetched channel page'}`);
  results.push({ json: { channelId, sourceUrl: item.json.channelUrl } });
}
return results;

const results = [];
for (const item of $input.all()) {
  const channel = item.json.items?.[0];
  const uploadsPlaylistId = channel?.contentDetails?.relatedPlaylists?.uploads;
  if (!channel || !uploadsPlaylistId) throw new Error(`YouTube Data API did not return an uploads playlist for channel ${item.json.items?.[0]?.id ?? 'unknown'}`);
  results.push({ json: { uploadsPlaylistId, channelId: channel.id, channelTitle: channel.snippet?.title ?? channel.id } });
}
return results;

const results = [];
for (const item of $input.all()) {
  for (const video of item.json.items ?? []) {
    const snippet = video.snippet ?? {};
    const videoId = video.contentDetails?.videoId ?? snippet.resourceId?.videoId;
    if (!videoId) continue;
    results.push({ json: {
      source: snippet.videoOwnerChannelTitle ?? snippet.channelTitle ?? 'YouTube',
      sourceType: 'youtube',
      title: snippet.title ?? '',
      link: `https://www.youtube.com/watch?v=${videoId}`,
      publishedAt: snippet.publishedAt ?? '',
      content: snippet.description ?? ''
    } });
  }
}
return results;

// Sheet columns: Type (youtube | threads), URL. For threads, URL may be a profile URL or @username.
const usernames = $input.all().map(i => i.json)
  .filter(r => String(r.Type ?? '').trim().toLowerCase() === 'threads')
  .map(r => String(r.URL ?? '').trim().replace(/^https?:\/\/(www\.)?threads\.(net|com)\//i, '').replace(/^@/, '').split(/[/?#]/)[0])
  .filter(u => /^[A-Za-z0-9._]+$/.test(u));
return [...new Set(usernames)].map(u => ({ json: { url: `https://rsshub.rssforever.com/threads/${u}`, source: `Threads: @${u}` } }));

return $input.all().map(item => ({ json: {
  source: 'Threads',
  sourceType: 'threads',
  title: item.json.title ?? '',
  link: item.json.link ?? item.json.url ?? '',
  publishedAt: item.json.isoDate ?? item.json.pubDate ?? item.json.published ?? '',
  content: item.json.contentSnippet ?? item.json.content ?? item.json.description ?? ''
} }));

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>\"]/g, character => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '\"': '&quot;'
  })[character]);
}

return $input.all().map(item => {
  let body = escapeHtml(item.json.output ?? '');
  body = body
    .replace(/\*\*\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)\*\*/g, '<p><a href="$2"><strong>$1</strong></a></p>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '<a href="$2">$1</a>')
    .replace(/^###\s+(.+)$/gm, '<h3>$1</h3>')
    .replace(/^##\s+(.+)$/gm, '<h2>$1</h2>')
    .replace(/^#\s+(.+)$/gm, '<h1>$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/^\s*[-*]\s+/gm, '&bull; ')
    .replace(/\n{2,}/g, '<br><br>')
    .replace(/\n/g, '<br>');
  return { json: { ...item.json, emailHtml: `<div style="font-family:Arial,sans-serif;line-height:1.5">${body}</div>` } };
});
